(@set07_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["librarian","The","renewed","the","book","for","two","weeks"]','the librarian renewed the book for two weeks',1,'Declarative order: subject (The librarian) + verb (renewed) + object (the book) + duration (for two weeks).',98),
(@set07_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["was","A","submitted","maintenance","ticket","on","the","portal"]','a maintenance ticket was submitted on the portal',1,'Passive order: subject (A maintenance ticket) + was + past participle (submitted) + place (on the portal).',99),
(@set07_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["will","The","begin","after","seminar","the","professor","finishes","her","introduction"]','the seminar will begin after the professor finishes her introduction',1,'Main clause (The seminar will begin) followed by the time clause (after the professor finishes her introduction).',100),
(@set07_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["roots","Mangrove","slow","the","water","and","trap","the","sediment"]','mangrove roots slow the water and trap the sediment',1,'Subject (Mangrove roots) with two linked verbs (slow the water, trap the sediment) joined by and.',101),
(@set07_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["designed","Harrison","a","pendulum","that","cancels","temperature","errors"]','harrison designed a pendulum that cancels temperature errors',1,'Subject (Harrison) + verb (designed) + object (a pendulum) + relative clause (that cancels temperature errors).',102),
(@set07_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["will","The","shop","close","early","for","a","private","event","museum","tonight"]','the museum shop will close early for a private event tonight',1,'Subject (The museum shop) + future verb (will close early) + purpose (for a private event) + time (tonight).',103),
(@set07_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["caught","Nina","the","express","after","missing","the","local","bus"]','nina caught the express after missing the local bus',1,'Main clause (Nina caught the express) + time phrase (after missing the local bus).',104),
(@set07_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["asked","The","applicant","to","swap","saturdays","with","another","student"]','the applicant asked to swap saturdays with another student',1,'Subject (The applicant) + verb + infinitive (asked to swap Saturdays) + phrase (with another student).',105),
(@set07_exam_id,'WRITING','WRITE_EMAIL','Write an email to your campus housing office (about 50-80 words) explaining that the heater in your room stopped working and asking when a technician can come. Greet the reader, state your room number, and close politely.',NULL,'NONE',NULL,NULL,0,'This item is saved for manual review; TestPrep does not auto-score writing. Aim for a clear request, a polite greeting and sign-off, and complete sentences.',106),
(@set07_exam_id,'WRITING','WRITE_EMAIL','Write a short email to a hiring manager (about 50-80 words) after your part-time interview, thanking them and confirming the Saturday shifts you discussed. Do not forget a greeting and your name at the end.',NULL,'NONE',NULL,NULL,0,'This item is saved for manual review; TestPrep does not auto-score writing. A good note thanks the manager, confirms availability, and stays brief.',107),
(@set07_exam_id,'WRITING','WRITE_DISCUSSION','Your professor is teaching a seminar on urban planning and asks: Do you agree that cities should replace concrete seawalls with mangrove forests wherever possible? Write a response of about 100 words contributing to the discussion. Claire argues that mangroves build land over time, something a wall never does. Marcus counters that mangroves only work on a gentle shore with the right water, so a city cannot rely on them everywhere.',NULL,'NONE',NULL,NULL,0,'Scored by manual review (auto_score 0). State your own position, engage with Claire''s or Marcus''s point, and add a reason or example.',108),
(@set07_exam_id,'WRITING','WRITE_DISCUSSION','Your professor asks: Should night-shift workers rotate their shifts forward rather than keep a fixed schedule? Write a response of about 100 words. Priya says a forward rotation matches the body clock better. Diego argues fixed shifts suit family life even if they clash with the circadian rhythm.',NULL,'NONE',NULL,NULL,0,'Scored by manual review (auto_score 0). Give your opinion, refer to one classmate''s view, and support your answer with a reason.',109);
